// Some portions generated by Claude
import { computeGraphLayout } from "./graph-layout-engine.ts";
import { initializeStressWasm } from "./graph-layout-wasm.ts";
import type { GraphLayoutReply, GraphLayoutRequest } from "./graph-layout-protocol.ts";

// Start the optional backend without holding a requested calculation behind a fetch. An early job can use JS;
// the retained worker uses the compiled Wasm module on later jobs after this prewarm completes.
void initializeStressWasm();

let running = false;
const reply = (message: GraphLayoutReply) => self.postMessage(message);

self.onmessage = async (event: MessageEvent<GraphLayoutRequest>) => {
  const { requestId, graph, options } = event.data;
  // A client leases this worker to one job at a time. Do not let an accidental second request interleave async work.
  if (running) {
    reply({ requestId, error: "The graph layout worker is already running a calculation." });
    return;
  }
  running = true;
  try {
    reply({ requestId, result: await computeGraphLayout(graph, options) });
  } catch (error) {
    reply({ requestId, error: error instanceof Error ? error.message : String(error) });
  } finally {
    running = false;
  }
};
